data class Glyph(val code: String, val w: Int, val h: Int)   // intrinsic state

object GlyphFactory {                             // FlyweightFactory
    private val pool = ConcurrentHashMap<String, Glyph>()
    fun of(code: String, w: Int, h: Int): Glyph =
        pool.computeIfAbsent(code) { Glyph(code, w, h) }
}

data class Cell(val glyph: Glyph, val x: Int, val y: Int)    // extrinsic state
